-- ============================================================
-- SEED AVENTUS REAL V2 - 403 PRODUCTOS (UPSERT IDEMPOTENTE)
-- Ejecutar en la consola SQL de Supabase
-- ============================================================
DO $$
DECLARE
  v_emp_id uuid;
  
  c_arabes uuid;
  c_tubitos uuid;
  c_onlyyou uuid;
  c_desodorantes uuid;
  c_midore uuid;
  c_plata uuid;
  c_miniaturas uuid;
  c_miniaturas50 uuid;
  c_pelo uuid;
  c_extractos uuid;
BEGIN
  -- 1. Asignar ID exacto de la empresa Aventus
  v_emp_id := '29689fc3-9d06-46fe-824c-7a3f73659aaf';
  
  -- 2. Asegurar que las 11 categorias existan (UPSERT)
  -- We will just select the IDs, and if not found, we insert and select again.
  -- Perfumes Árabes
  SELECT id INTO c_arabes FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes Árabes' LIMIT 1;
  IF c_arabes IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes Árabes', '🕌', 1) RETURNING id INTO c_arabes; END IF;
  
  -- Perfumes Extractos
  SELECT id INTO c_extractos FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes Extractos' LIMIT 1;
  IF c_extractos IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes Extractos', '⚗️', 2) RETURNING id INTO c_extractos; END IF;

  -- Perfumes Midoré
  SELECT id INTO c_midore FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes Midoré' LIMIT 1;
  IF c_midore IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes Midoré', '🛢️', 3) RETURNING id INTO c_midore; END IF;

  -- Desodorantes Árabes
  SELECT id INTO c_desodorantes FROM categories WHERE empresa_id = v_emp_id AND name = 'Desodorantes Árabes' LIMIT 1;
  IF c_desodorantes IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Desodorantes Árabes', '💨', 4) RETURNING id INTO c_desodorantes; END IF;

  -- Perfumes ONLYYOU
  SELECT id INTO c_onlyyou FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes ONLYYOU' LIMIT 1;
  IF c_onlyyou IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes ONLYYOU', '💛', 5) RETURNING id INTO c_onlyyou; END IF;

  -- Perfumes PLATA
  SELECT id INTO c_plata FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes PLATA' LIMIT 1;
  IF c_plata IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes PLATA', '🥈', 6) RETURNING id INTO c_plata; END IF;

  -- Perfumes Miniaturas
  SELECT id INTO c_miniaturas FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes Miniaturas' LIMIT 1;
  IF c_miniaturas IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes Miniaturas', '🍾', 7) RETURNING id INTO c_miniaturas; END IF;

  -- Perfumes Miniaturas 50 ML
  SELECT id INTO c_miniaturas50 FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes Miniaturas 50 ML' LIMIT 1;
  IF c_miniaturas50 IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes Miniaturas 50 ML', '🍾', 8) RETURNING id INTO c_miniaturas50; END IF;

  -- Perfumes Tubitos
  SELECT id INTO c_tubitos FROM categories WHERE empresa_id = v_emp_id AND name = 'Perfumes Tubitos' LIMIT 1;
  IF c_tubitos IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Perfumes Tubitos', '🧴', 9) RETURNING id INTO c_tubitos; END IF;

  -- Productos de Pelo
  SELECT id INTO c_pelo FROM categories WHERE empresa_id = v_emp_id AND name = 'Productos de Pelo' LIMIT 1;
  IF c_pelo IS NULL THEN INSERT INTO categories (empresa_id, name, icon, sort_order) VALUES (v_emp_id, 'Productos de Pelo', '💇', 10) RETURNING id INTO c_pelo; END IF;

  -- 3. Crear una tabla temporal para cargar los productos masivamente y luego hacer el MERGE/UPSERT
  CREATE TEMP TABLE tmp_products (
    category_id uuid,
    name text,
    description text,
    price numeric,
    image_url text,
    code text,
    sort_order integer
  ) ON COMMIT DROP;

  -- 4. Insertar en tabla temporal

  -- 5. Hacer el UPSERT (Actualizar si existe nombre+categoría, Insertar si no existe)
  -- Para esto, como no hay UNIQUE constraint en nombre+categoría, lo hacemos con UPDATE y luego INSERT
  
  -- Actualizar existentes
  UPDATE products p
  SET price = t.price,
      description = t.description,
      image_url = t.image_url,
      code = t.code,
      sort_order = t.sort_order,
      is_active = true
  FROM tmp_products t
  WHERE p.empresa_id = v_emp_id 
    AND p.name = t.name 
    AND p.category_id = t.category_id;
    
  -- Insertar faltantes
  SELECT v_emp_id, t.category_id, t.name, t.description, t.price, t.image_url, t.code, t.sort_order, true
  FROM tmp_products t
  WHERE NOT EXISTS (
    SELECT 1 FROM products p 
    WHERE p.empresa_id = v_emp_id 
      AND p.name = t.name 
      AND p.category_id = t.category_id
  );

END $$;
